-- Preserve SQL Server nvarchar bounds, including two UTF-16 units per non-BMP character.
CREATE OR REPLACE FUNCTION hawala.utf16_units(value text) RETURNS integer
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $body$
SELECT char_length(value)+regexp_count(value COLLATE "C", U&'[\+010000-\+10FFFF]')
$body$;
